import {preset,validate,inputFromRecord} from './moving-wheel.js';
const $=id=>document.getElementById(id),form=$('setup'),keys=['hubMass','tyreMass','centerX','height','velocityX','velocityZ','omega','duration','nodes','dt'];let input=preset('flat'),applied,worker,revision=0,dirty=true,playing=false,index=0,lastStamp=0,elapsed=0,animation=0;
const inputs=r=>({params:r.params,profile:r.profile,assembly:r.assembly});
function pause(){playing=false;cancelAnimationFrame(animation);animation=0;$('play').textContent='Play';lastStamp=0;}
function controls(){const ok=!dirty&&!!applied?.frames.length;for(const id of ['play','reset','step','scrub'])$(id).disabled=!ok;$('save').disabled=dirty||!applied;}
function stop(){revision++;worker?.terminate();worker=null;$('cancel').disabled=true;pause();}
function edits(){stop();dirty=true;controls();$('status').textContent='UNAPPLIED EDITS';}
function reject(error){edits();$('status').textContent='INPUT REJECTED';$('error').textContent=error.message;}
function fill(a){const dt=form.elements.dt;dt.querySelectorAll('[data-authored]').forEach(o=>o.remove());if(!Array.from(dt.options).some(o=>o.value===String(a.params.dt))){const o=new Option((a.params.dt*1000)+' ms (authored)',String(a.params.dt));o.dataset.authored='true';dt.add(o);}$('example').value=a.params.fixture;for(const key of keys)form.elements[key].value=String(a.params[key]);$('setupText').value=JSON.stringify(a,null,2);}
function calculate(a){input=structuredClone(a);stop();const ticket=revision;dirty=true;controls();$('status').textContent='CALCULATING';$('error').textContent='';$('cancel').disabled=false;worker=new Worker(new URL('./moving-wheel-worker.js',import.meta.url),{type:'module'});worker.onerror=()=>{if(ticket===revision)reject(Error('Moving-wheel worker failed. Apply again to retry.'));};worker.onmessage=e=>{if(ticket!==revision)return;if(e.data.error){reject(Error(e.data.error));return;}applied=e.data.result;input=inputs(applied);stop();dirty=false;index=0;elapsed=0;fill(input);$('scrub').max=Math.max(0,applied.frames.length-1);controls();render();};worker.postMessage(a);}
function render(){if(!applied)return;const r=applied,f=r.frames[index];$('status').textContent=r.status.toUpperCase().replaceAll('-',' ');$('scrub').value=index;$('time').textContent=f?f.time.toFixed(4)+' s':'—';$('force').textContent=f?Math.hypot(...f.groundWrench.slice(0,2)).toFixed(1)+' N':'—';$('speed').textContent=f?f.velocity[1].toFixed(3)+' m/s':'—';$('reason').textContent=r.termination?`Stopped: ${r.termination.reason} at ${r.termination.time.toFixed(6)} s. ${r.status==='terminated'?'The attempted step was rejected; this is the last accepted state.':'No motion is admitted.'}`:'Run complete within the declared model limits.';$('summary').textContent=r.summary?`Peak ${r.summary.peakForce.toFixed(1)} N · overlap ${(1000*r.summary.peakPenetration).toFixed(3)} mm`:'';$('ledger').textContent=f?`Energy ${f.energy.toFixed(4)} J · external work ${f.externalWork.toFixed(4)} J · signed constraint work ${f.constraintWork.toFixed(4)} J · edge damping loss ${f.dampingLoss.toFixed(4)} J · balance residual ${f.residual.toExponential(2)} J. Constraint work includes soft-contact storage/release; it is not all dissipation.`:'';$('assemblyStatus').textContent=r.assessment.status==='unknown'?'Assembly evidence unknown. This is an uncalibrated mechanics experiment; no service or survival certification.':r.assessment.status==='incompatible'?'Declared assembly or inflation violation: motion blocked.':'Within declared service limits; no survival certification.';draw();history();}
function canvas(id){const el=$(id),w=el.clientWidth,h=el.clientHeight;if(w<40||h<40)return null;const dpr=devicePixelRatio||1;el.width=Math.round(w*dpr);el.height=Math.round(h*dpr);const c=el.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);return {c,w,h};}
function arrow(c,x,z,fx,fz,color,scale){const dx=fx*scale,dz=-fz*scale,len=Math.hypot(dx,dz);if(len<.1)return;c.strokeStyle=color;c.fillStyle=color;c.lineWidth=1.4;c.beginPath();c.moveTo(x,z);c.lineTo(x+dx,z+dz);c.stroke();const ux=dx/len,uz=dz/len;c.beginPath();c.moveTo(x+dx,z+dz);c.lineTo(x+dx-6*ux+3*uz,z+dz-6*uz-3*ux);c.lineTo(x+dx-6*ux-3*uz,z+dz-6*uz+3*ux);c.closePath();c.fill();}
function draw(){if(!applied)return;const view=canvas('rig');if(!view)return;const {c,w,h}=view,r=applied,p=r.params,f=r.frames[index],frames=r.frames.length?r.frames:[{hub:[p.centerX,p.height,p.rotation]}],xs=frames.map(a=>a.hub[0]),zs=frames.map(a=>a.hub[1]),xmin=Math.min(...xs)-p.radius-.08,xmax=Math.max(...xs)+p.radius+.08,zmin=Math.min(...zs)-p.radius-.1,zmax=Math.max(...zs)+p.radius+.1,scale=Math.min((w-30)/(xmax-xmin),(h-40)/(zmax-zmin)),x=v=>w/2+(v-(xmin+xmax)/2)*scale,z=v=>h/2-(v-(zmin+zmax)/2)*scale,hub=f?.hub??[p.centerX,p.height,p.rotation];
 c.save();c.beginPath();c.rect(6,24,w-12,h-32);c.clip();c.strokeStyle='#83979d';c.lineWidth=2;c.beginPath();r.profile.points.forEach((q,i)=>i?c.lineTo(x(q[0]),z(q[1])):c.moveTo(x(q[0]),z(q[1])));c.stroke();c.strokeStyle='#42586b';c.setLineDash([3,4]);c.beginPath();frames.forEach((a,i)=>i?c.lineTo(x(a.hub[0]),z(a.hub[1])):c.moveTo(x(a.hub[0]),z(a.hub[1])));c.stroke();c.setLineDash([]);
 c.strokeStyle='#70e2ce';c.lineCap='round';c.lineJoin='round';c.lineWidth=2*p.skin*scale;if(f){c.beginPath();f.nodes.forEach((q,i)=>i?c.lineTo(x(q[0]),z(q[1])):c.moveTo(x(q[0]),z(q[1])));c.closePath();c.stroke();}else{c.setLineDash([4,4]);c.lineWidth=1;c.beginPath();c.arc(x(hub[0]),z(hub[1]),p.radius*scale,0,2*Math.PI);c.stroke();c.setLineDash([]);}
 c.strokeStyle='#c2a3ff';c.lineWidth=1.5;c.beginPath();c.arc(x(hub[0]),z(hub[1]),p.rimRadius*scale,0,2*Math.PI);c.moveTo(x(hub[0]),z(hub[1]));c.lineTo(x(hub[0]+p.rimRadius*Math.cos(hub[2])),z(hub[1]-p.rimRadius*Math.sin(hub[2])));c.stroke();if(f){for(const a of f.contacts)arrow(c,x(a.point[0]),z(a.point[1]),...a.force,'#f2b373',.0004*scale);arrow(c,x(hub[0]),z(hub[1]),f.groundWrench[0],f.groundWrench[1],'#84c8ff',.0004*scale);}c.restore();c.fillStyle='#9aabb7';c.font='11px system-ui';c.fillText('x →  z ↑ · equal scale · frictionless contact',10,16);
}
function history(){if(!applied)return;const view=canvas('history');if(!view)return;const {c,w,h}=view,frames=applied.frames;if(!frames.length)return;const xmax=frames.at(-1).time||1,tracks=[{value:a=>a.groundWrench[1],label:'Vertical ground force / N',color:'#f2b373'},{value:a=>a.residual,label:'Energy balance residual / J',color:'#70e2ce'}];c.font='11px system-ui';tracks.forEach((track,j)=>{const top=j*h/2+22,bottom=(j+1)*h/2-12,vals=frames.map(track.value),lo=Math.min(0,...vals),hi=Math.max(1e-8,...vals),x=t=>42+(w-54)*t/xmax,z=v=>bottom-(bottom-top)*(v-lo)/(hi-lo);c.fillStyle='#9aabb7';c.fillText(track.label,8,top-7);c.fillText(hi.toPrecision(3),4,top+8);c.strokeStyle='#344654';c.beginPath();c.moveTo(42,z(0));c.lineTo(w-12,z(0));c.stroke();c.strokeStyle=track.color;c.beginPath();frames.forEach((a,i)=>i?c.lineTo(x(a.time),z(track.value(a))):c.moveTo(x(a.time),z(track.value(a))));c.stroke();c.strokeStyle='#c2a3ff';c.beginPath();c.moveTo(x(frames[index].time),top);c.lineTo(x(frames[index].time),bottom);c.stroke();});}
form.oninput=edits;form.onsubmit=e=>{e.preventDefault();try{const a=structuredClone(input);for(const key of keys)a.params[key]=form.elements[key].value.trim()?Number(form.elements[key].value):NaN;a.params=validate(a.params);calculate(a);}catch(error){reject(error);}};$('setupText').oninput=edits;$('applyJson').onclick=()=>{try{const text=$('setupText').value;if(new TextEncoder().encode(text).length>8*1024*1024)throw Error('Input exceeds 8 MiB.');calculate(JSON.parse(text));}catch(error){reject(error);}};
$('example').onchange=()=>{const a=preset($('example').value);fill(a);calculate(a);};$('restore').onclick=()=>{if(!applied)return;stop();input=inputs(applied);dirty=false;fill(input);$('error').textContent='';controls();render();};$('cancel').onclick=()=>{edits();$('status').textContent='CANCELLED';};$('scrub').oninput=()=>{pause();index=Number($('scrub').value);elapsed=applied.frames[index].time;render();};$('reset').onclick=()=>{pause();index=0;elapsed=0;render();};$('step').onclick=()=>{pause();index=Math.min(index+1,applied.frames.length-1);elapsed=applied.frames[index].time;render();};$('play').onclick=()=>{if(playing){pause();return;}if(index===applied.frames.length-1){index=0;elapsed=0;}playing=true;$('play').textContent='Pause';lastStamp=0;animation=requestAnimationFrame(tick);};
function tick(stamp){if(!playing||dirty)return;if(lastStamp)elapsed+=Math.min((stamp-lastStamp)/1000,.05);lastStamp=stamp;while(index<applied.frames.length-1&&applied.frames[index+1].time<=elapsed)index++;render();if(index===applied.frames.length-1)pause();else animation=requestAnimationFrame(tick);}
$('load').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;edits();const ticket=revision;try{if(file.size>8*1024*1024)throw Error('Record exceeds 8 MiB.');const text=await file.text();if(ticket!==revision)return;calculate(inputFromRecord(JSON.parse(text.replace(/^\uFEFF/,''))));}catch(error){if(ticket===revision)reject(error);}};$('save').onclick=()=>{if(dirty||!applied)return;const url=URL.createObjectURL(new Blob([JSON.stringify(applied)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='bikelab-moving-wheel.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
new ResizeObserver(()=>{draw();history();}).observe($('rig'));window.addEventListener('resize',()=>{draw();history();});window.addEventListener('pagehide',()=>{if(worker)edits();pause();});fill(input);calculate(input);
